let saved={};try{saved=JSON.parse(localStorage.getItem('photosynthesisQuest')||'{}')}catch(e){}
const persistent=Object.assign(defaultState(),saved);let score=persistent.score||0,done=persistent.done||[false,false,false,false,false],current=-1;
let activity={};let quiz={choice:null,choiceRight:false,reasonDone:false};let toastTimer;
const app=document.getElementById('app');
function save(){try{localStorage.setItem('photosynthesisQuest',JSON.stringify({score,done}))}catch(e){}document.getElementById('topScore').textContent=String(score).padStart(3,'0')}
function addPoints(n,msg){score+=n;save();showToast(`+${n} Photosynthesis Points${msg?' · '+msg:''}`)}
function showToast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function freshActivity(i){return i===0?{year:0,watered:false,weighed:false}:i===1?{pairs:{},selectedLabel:null,prism:false}:i===2?{phase:0,water:0,co2:0,energy:false,eq:[null,null,null,null],eqActive:0,eqDone:false}:i===3?{tested:[false,false],predicted:false}:i===4?{temp:25,co2:420,light:65,farm:[],optimized:false}:{} }
function openModule(i){current=i;activity=freshActivity(i);quiz={choice:null,choiceRight:false,reasonDone:false};render()}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function completedActivity(i){const a=activity,m=modules[i];if(i===0)return a.weighed;if(i===1)return Object.keys(a.pairs).length===3&&a.prism;if(i===2)return a.phase>=2&&a.co2>=3&&a.energy&&a.eqDone;if(i===3)return a.tested.every(Boolean);if(i===4)return a.optimized&&a.farm.length===3;return false}
function moduleCard(i){return `<article class="module-card ${done[i]?'done':''}" data-open="${i}"><span class="card-num">0${i+1} / 05</span><span class="card-icon">${modules[i].icon}</span><h3>${modules[i].short}</h3><p>${['Recreate the willow experiment.','Explore a plant cell’s power lab.','Turn light into a glucose model.','Run a starch-detective test.','Tune a vertical farm.'][i]}</p>${done[i]?'<span class="card-status">✓ COMPLETE</span>':''}</article>`}
function renderHome(){app.innerHTML=`<section class="home-grid"><div class="hero"><div class="eyebrow">A hands-on journey through plant science</div><h1>Photosynthesis<br><em>Quest</em>: Master<br>of Energy</h1><p class="hero-copy">How does a tiny seedling turn sunlight into a forest? Step into the lab, run the experiments, and follow the energy.</p><button class="button" data-open="${done.findIndex(x=>!x)>=0?done.findIndex(x=>!x):0}">START YOUR QUEST <span class="arrow">↗</span></button><div class="hero-bottom"><div class="avatars"><i>🌿</i><i>🔬</i><i>☀️</i></div><span>5 field missions · Ages 11–14</span></div></div><div class="hero-art"><span class="orbit o1">☀️</span><span class="orbit o2">CO₂</span><span class="orbit o3">H₂O</span><span class="orbit o4">✦</span><div class="hero-leaf">🌿</div><span class="art-caption">FIG 01 · ENERGY IN MOTION</span></div></section><section class="home-modules"><div class="section-heading"><div><div class="eyebrow">Choose a mission</div><h2>Your field guide</h2></div><small>${done.filter(Boolean).length} OF 5 MISSIONS COMPLETE</small></div><div class="module-grid">${modules.map((_,i)=>moduleCard(i)).join('')}</div></section>`}
function renderSidebar(){const progress=done.filter(Boolean).length;return `<aside class="sidebar"><button class="back-link" data-home>← &nbsp;FIELD GUIDE</button><h2 class="sidebar-title">Your field guide</h2><p class="sidebar-desc">Five missions to master plant energy.</p><div class="progress-track"><span style="width:${progress*20}%"></span></div><nav class="side-nav">${modules.map((m,i)=>`<div class="side-module ${i===current?'active':''} ${done[i]?'complete':''}" data-open="${i}"><span class="side-icon">${m.icon}</span><span class="side-label">${m.short}</span>${done[i]?'<span class="side-check">✓</span>':''}</div>`).join('')}</nav><div class="side-score">YOUR PHOTOSYNTHESIS POINTS<strong>✦ ${score}</strong></div></aside>`}
function renderModule(){const m=modules[current];app.innerHTML=`<div class="game-grid">${renderSidebar()}<section class="content"><header class="module-heading"><div><div class="eyebrow">MISSION 0${current+1} · ${esc(m.kicker)}</div><h1>${esc(m.title)}</h1><p>${esc(m.desc)}</p></div><span class="level-tag">${done[current]?'✓ MASTERED':'FIELD LAB · 0'+(current+1)}</span></header><div class="lab-panel">${renderActivity()}${completedActivity(current)?renderQuiz():''}</div>${done[current]?`<div class="finish-note">Mission complete! You can revisit the lab or head to another field mission. Your points are saved on this device.</div>`:''}</section></div>`;updateScoreUI()}
function updateScoreUI(){document.getElementById('topScore').textContent=String(score).padStart(3,'0')}
function renderActivity(){switch(current){case 0:return willow();case 1:return chloroplast();case 2:return arcade();case 3:return detective();case 4:return farm();}}
function willow(){const a=activity;return `<div class="panel-top"><span class="panel-label">THE WILLOW EXPERIMENT · 1648–1653</span><span class="panel-step">${a.weighed?'RESULTS RECORDED':`YEAR ${Math.min(a.year+1,5)} OF 5`}</span></div><div class="activity-row"><div class="activity-visual"><span class="sun">☀️</span><span class="sapling">${a.year<2?'🌱':a.year<4?'🪴':'🌳'}</span><span class="soil"></span></div><div class="activity-info"><h3>${a.weighed?'A surprising result.':'Grow the willow.'}</h3><p>${a.weighed?'The tree gained enormous mass, while the dry soil barely changed. Where did the tree’s new material come from?':`Plant the ${a.year===0?'sapling':'growing willow'} in dry soil. Water it once each simulated year; the sunlight and air are part of the experiment too.`}</p><div class="year-dots">${[1,2,3,4,5].map(y=>`<span class="year-dot ${y<=a.year?'active':''}">${y}</span>`).join('')}</div><div class="stat-row"><div class="stat-box"><span>WILLOW MASS</span><strong>${a.weighed?'74.8 kg':`${Math.round(0.06+a.year*14.94)} kg`}</strong></div><div class="stat-box"><span>DRY SOIL</span><strong>${a.weighed?'−0.06 kg':`${a.year===0?'90.0':(90-a.year*.01).toFixed(2)} kg`}</strong></div></div><div class="inline-actions">${!a.weighed?`<button class="activity-btn primary" data-action="${a.watered?'year':'water'}" ${a.year>=5&&a.watered?'disabled':''}>${a.watered?'Advance one year ↗':'💧 Water the willow'}</button>${a.year>=5&&a.watered?'<button class="activity-btn primary" data-action="weigh">Weigh the results ⚖</button>':''}`:'<span class="mini-note">The tiny soil change cannot account for the tree’s growth.</span>'}</div><div class="feedback" id="activityFeedback">${a.watered&&!a.weighed?'Water absorbed. Advance time to continue.':''}</div></div></div>${a.weighed?`<div class="mini-note"><b>Field note:</b> Van Helmont’s measurement was important, but he did not account for gases. Modern science shows plants make most of their biomass from carbon dioxide and water—not soil.</div><div class="challenge"><h3>Quick check · Where does new plant mass come from?</h3>${questionOptions()}</div>${reasonBlock()}`:''}${activityFooter()}`}
function questionOptions(){const m=modules[current];return `<div class="options">${m.choices.map((x,j)=>`<button class="option ${quiz.choice===j?(j===m.answer?'correct':'wrong'):''}" data-choice="${j}" ${quiz.choice!==null?'disabled':''}>${String.fromCharCode(65+j)}. ${esc(x)}</button>`).join('')}</div><div class="feedback ${quiz.choice!==null&&!quiz.choiceRight?'bad':''}">${quiz.choiceRight?'Correct! A sharp scientific observation.':quiz.choice!==null?'Not quite—read the evidence and try this mission again.':''}</div>`}
function reasonBlock(){const m=modules[current];return `<div class="challenge"><h3>Give a reason · Think like a scientist</h3><p class="reason-hint">${esc(m.reasonHint)}</p><div class="reason-row"><input id="reasonInput" placeholder="Explain your thinking in a sentence…" value="${esc(quiz.reasonText||'')}" ${quiz.reasonDone?'disabled':''}><button class="activity-btn primary" data-action="reason" ${quiz.reasonDone?'disabled':''}>${quiz.reasonDone?'Reason saved ✓':'Check my reason'}</button></div><div class="feedback" id="reasonFeedback">${quiz.reasonDone?esc(m.reasonText||'Reason accepted — excellent scientific thinking.'):''}</div></div>`}
function activityFooter(){return `<div class="activity-footer"><span class="quest-progress">${done[current]?'MISSION MASTERED':completedActivity(current)?'ACTIVITY COMPLETE · ANSWER THE CHALLENGES':'COMPLETE THE LAB TO UNLOCK YOUR CHALLENGE'}</span>${completedActivity(current)&&quiz.choiceRight&&quiz.reasonDone&&!done[current]?`<button class="button lime" data-action="finish">${current===4?'COMPLETE QUEST':'NEXT MISSION'} <span class="arrow">→</span></button>`:''}</div>`}
function chloroplast(){const a=activity;return `<div class="panel-top"><span class="panel-label">PLANT CELL · CHLOROPLAST ZOOM</span><span class="panel-step">${Object.keys(a.pairs).length}/3 STRUCTURES MATCHED</span></div><div class="activity-row"><div class="activity-visual"><span class="cell-art">🟢</span><div class="chloroplast-scene"><div class="grana-stack"><i></i><i></i><i></i></div><span class="stroma-text">stroma</span><div class="grana-stack"><i></i><i></i><i></i></div></div></div><div class="activity-info"><h3>Match the parts.</h3><p>Drag a structure onto its function—or tap one from each column. Match all three to open the light lab.</p><div class="match-grid"><div class="match-column"><h4>STRUCTURE</h4>${pairData.map((p,i)=>`<div class="match-item ${a.pairs[i]?'paired':''}" draggable="true" data-label="${i}">${a.pairs[i]?'✓ ':''}${p.label}</div>`).join('')}</div><div class="match-column"><h4>FUNCTION</h4>${pairData.map((p,i)=>`<div class="match-item ${Object.values(a.pairs).includes(i)?'paired':''}" data-function="${i}">${Object.values(a.pairs).includes(i)?'✓ ':''}${p.func}</div>`).join('')}</div></div></div></div><div class="feedback" id="activityFeedback">${a.prism?'🌈 White light separates into visible colours. Chlorophyll absorbs light energy; its electrons become excited.':'Tip: double membrane = boundary; stroma = fluid; grana = stacks.'}</div><div class="challenge"><h3>Physics & chemistry link · Shine white light through a prism</h3><div class="prism-strip"></div><p class="reason-hint">A triangular prism separates visible white light into a spectrum. What happens to chlorophyll’s electrons when it absorbs light?</p><button class="activity-btn ${a.prism?'':'primary'}" data-action="prism" ${a.prism?'disabled':''}>${a.prism?'Spectrum observed ✓':'Pass light through the prism 🌈'}</button></div>${a.prism&&Object.keys(a.pairs).length===3?`<div class="challenge"><h3>Quick check · What can visible light do?</h3>${questionOptions()}</div>${reasonBlock()}`:''}${activityFooter()}`}
function arcade(){const a=activity;let activityContent='';if(a.phase===0)activityContent=`<div class="activity-info"><h3>Stage A · Charge the grana</h3><p>Light excites chlorophyll. Split water, release oxygen, and store energy for the next stage.</p><div class="stage-meter">${[1,2,3].map(n=>`<i class="meter-cell ${n<=a.water?'on':''}"></i>`).join('')}</div><div class="inline-actions"><button class="activity-btn primary" data-action="photon" ${a.energy?'disabled':''}>☀ Absorb a photon</button><button class="activity-btn" data-action="split" ${!a.energy||a.water>=3?'disabled':''}>💧 Split water (${a.water}/3)</button><button class="activity-btn" data-action="oxygen" ${a.water<3||a.phase!==0?'disabled':''}>Release O₂ + store energy</button></div><div class="feedback">${a.energy?(a.water>=3?'Water split! Release oxygen and store the energy.':'Chlorophyll excited! Now split three water molecules.'):''}</div></div>`;else if(a.phase===1)activityContent=`<div class="activity-info"><h3>Stage B · Build in the stroma</h3><p>Use stored energy and hydrogen with carbon dioxide in the Calvin cycle. Collect three CO₂ molecules to build one glucose.</p><div class="stat-row"><div class="stat-box"><span>STORED ENERGY</span><strong>⚡ Ready</strong></div><div class="stat-box"><span>CO₂ COLLECTED</span><strong>${a.co2} / 3</strong></div></div><div class="inline-actions"><button class="activity-btn primary" data-action="co2" ${a.co2>=3?'disabled':''}>＋ Add CO₂</button><button class="activity-btn" data-action="glucose" ${a.co2<3?'disabled':''}>⚡ Assemble glucose</button></div><div class="feedback">${a.co2>=3?'Enough carbon collected—use stored energy to assemble sugar.':''}</div></div>`;else activityContent=`<div class="activity-info"><h3>Glucose assembled! ✨</h3><p>Now balance the photosynthesis equation. Fill each slot with the correct molecule and coefficient.</p><div class="molecule-row"><div class="molecule">CARBON DIOXIDE<div class="atom-line"><i class="atom.o">O</i><i class="atom bond"></i><i class="atom.c">C</i><i class="atom bond"></i><i class="atom.o">O</i></div></div><div class="molecule">WATER<div class="atom-line"><i class="atom.h">H</i><i class="atom bond"></i><i class="atom.o">O</i><i class="atom bond"></i><i class="atom.h">H</i></div></div><div class="molecule">OXYGEN<div class="atom-line"><i class="atom.o">O</i><i class="atom bond"></i><i class="atom.o">O</i></div></div></div><div class="equation">${a.eq.map((x,j)=>`<div class="equation-slot ${x?'filled':''}" data-eq-slot="${j}">${x||['Reactant 1','Reactant 2','Product 1','Product 2'][j]}</div>${j===0?'<span>+</span>':j===1?'<span>→</span>':j===2?'<span>+</span>':''}`).join('')}</div><div class="equation-controls">${['6CO₂','6H₂O','C₆H₁₂O₆','6O₂'].map(x=>`<button class="activity-btn" data-eq-value="${x}">${x}</button>`).join('')}</div><div class="inline-actions" style="justify-content:center"><button class="activity-btn primary" data-action="equation">Check balanced equation</button><button class="activity-btn" data-action="clearEquation">Reset</button></div><div class="feedback" style="text-align:center">${a.eqDone?'Perfectly balanced! 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂':'Select a slot, then a molecule. Balance atoms on both sides.'}</div></div>`;
return `<div class="panel-top"><span class="panel-label">${a.phase===0?'STAGE A · LIGHT-DEPENDENT · GRANA':a.phase===1?'STAGE B · CALVIN CYCLE · STROMA':'MOLECULAR MODELLING · BALANCED EQUATION'}</span><span class="panel-step">${a.phase===0?'01 / 03':a.phase===1?'02 / 03':'03 / 03'}</span></div><div class="activity-row"><div class="activity-visual">${a.phase===2?'<div style="font-size:45px;animation:pulse 1.4s infinite">🍬</div>':'<div style="text-align:center"><div style="font-size:39px">'+(a.energy?'✨':'☀️')+'</div><div class="chloroplast-scene" style="width:128px;height:76px;border-width:6px;margin:6px auto"><div class="grana-stack"><i></i><i></i><i></i></div><span class="stroma-text">'+(a.phase?'stroma':'grana')+'</span></div><div class="molecule-row"><span class="molecule">H₂O × ${a.water}</span><span class="molecule">O₂</span></div></div></div>${activityContent}</div>${a.phase===2&&a.eqDone?`<div class="challenge"><h3>Quick check · Trace the energy</h3>${questionOptions()}</div>${reasonBlock()}`:''}${activityFooter()}`}

function detective(){const a=activity;return `<div class="panel-top"><span class="panel-label">STARCH DETECTIVE · IODINE TEST</span><span class="panel-step">${a.tested.filter(Boolean).length}/2 LEAVES TESTED</span></div><div class="activity-row"><div class="activity-visual"><div style="text-align:center"><div class="iodine-leaf ${a.tested[0]?'tested':''}"><i class="leaf-vein"></i></div><div class="mini-note" style="margin-top:19px">${a.tested[0]?'TESTED · GREEN AREAS TURN BLUE-BLACK':'A · VARIEGATED LEAF'}</div></div></div><div class="activity-info"><h3>${a.tested[0]&&a.tested[1]?'Evidence collected.':'Predict, then add iodine.'}</h3><p>Leaf A has green and white patches. Leaf B is green, but some of it was covered with opaque tape before the test.</p><div style="display:flex;justify-content:center;gap:15px;align-items:center;margin:15px 0"><div class="iodine-leaf ${a.tested[0]?'tested':''}"><i class="leaf-vein"></i></div><div style="font-size:23px">→</div><div class="iodine-leaf ${a.tested[1]?'tested taped':''}"><i class="leaf-vein"></i></div></div><div class="stat-row"><div class="stat-box"><span>IODINE BEFORE</span><strong>🟤 Yellow-brown</strong></div><div class="stat-box"><span>STARCH + IODINE</span><strong>🔵 Blue-black</strong></div></div><div class="inline-actions"><button class="activity-btn primary" data-action="iodine" ${a.tested[0]?'disabled':''}>Add iodine to leaf A</button><button class="activity-btn primary" data-action="tapeIodine" ${a.tested[1]?'disabled':''}>Add iodine to taped leaf B</button></div><div class="feedback">${a.tested[0]||a.tested[1]?'Blue-black appears only where starch was made: in green areas exposed to light.':'Predict: will the white patch or taped area make starch?'}</div></div></div>${a.tested.every(Boolean)?`<div class="mini-note"><b>Observation:</b> iodine turns blue-black where starch is present. Green, uncovered leaf tissue had both chlorophyll and light; white tissue lacked chlorophyll, and taped tissue lacked light.</div><div class="challenge"><h3>Quick check · Read the evidence</h3>${questionOptions()}</div>${reasonBlock()}`:''}${activityFooter()}`}
function calcRate(t,c,l){const temp=Math.max(0,100-Math.pow((t-27)/24,2)*100);const co2=100*(c/(c+220));const light=100*(l/(l+22));return Math.round((temp*co2*light/10000)*1.5)}
function graphSvg(){const pts=[];for(let i=0;i<=12;i++){const t=5+i*3.5;const v=calcRate(t,Number(activity.co2),Number(activity.light));pts.push(`${i*100/12},${100-v}`)}return `<svg viewBox="0 0 100 100" preserveAspectRatio="none"><polyline points="${pts.join(' ')}" fill="none" stroke="#83a747" stroke-width="2.3" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${Math.min(100,Math.max(0,(activity.temp-5)/42*100))}" cy="${100-calcRate(activity.temp,activity.co2,activity.light)}" r="3" fill="#ef8d5d" vector-effect="non-scaling-stroke"/></svg>`}
function farm(){const a=activity;const rate=calcRate(+a.temp,+a.co2,+a.light);return `<div class="panel-top"><span class="panel-label">GROWTH CONTROL · SIMULATION</span><span class="panel-step">PHOTOSYNTHESIS RATE</span></div><div class="activity-row"><div class="activity-visual" style="display:block;padding:15px"><div style="font:9px var(--mono);color:#829078">RATE vs TEMPERATURE</div><div class="graph" id="farmGraph">${graphSvg()}</div><div class="graph-labels"><span>5°C</span><span>25°C</span><span>45°C</span></div><div class="rate-badge"><span>SIMULATED RATE</span><strong id="rateValue">${rate} units</strong></div></div><div class="activity-info"><h3>Find the sweet spot.</h3><p>Adjust one variable at a time. Rate rises with light and CO₂ until another factor limits it; very high temperatures reduce enzyme activity.</p>${[['temp','Temperature','°C',0,50,1],['co2','Carbon dioxide','ppm',0,1000,10],['light','Light intensity','%',0,100,1]].map(([key,label,unit,min,max,step])=>`<div class="factor-control"><label for="${key}Range">${label}</label><output id="${key}Value">${a[key]} ${unit}</output><input id="${key}Range" data-factor="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${a[key]}"></div>`).join('')}<button class="activity-btn primary" data-action="optimize" ${a.optimized?'disabled':''}>${a.optimized?'Optimal conditions recorded ✓':'Lock in my best conditions'}</button><div class="feedback" id="farmFeedback">${a.optimized?`Conditions recorded at ${rate} rate units.`:'Aim for a high rate: warm, not too hot, with plenty of light and CO₂.'}</div></div></div>${a.optimized?`<div class="challenge"><h3>Bonus · Design a vertical farm</h3><p class="reason-hint">Select all three features to build a land-saving skyscraper growing system.</p><div class="farm-tiles">${[['stack','🏙️','Stacked growing floors'],['light','💡','Artificial LED lighting'],['hydro','💧','Hydroponic nutrient water']].map(([id,icon,label])=>`<button class="farm-tile ${a.farm.includes(id)?'active':''}" data-farm="${id}"><span>${icon}</span>${label}</button>`).join('')}</div><div class="farm-building">${[1,2,3].map((_,i)=>`<div class="tower">${[1,2,3].map(()=>`<i style="opacity:${a.farm.includes('light')?1:.4}"></i>`).join('')}</div>`).join('')}</div><div class="feedback">${a.farm.length===3?'Farm designed! Stacked floors, LEDs and hydroponics can help grow food where arable land is scarce.':`Design features selected: ${a.farm.length}/3`}</div></div><div class="challenge"><h3>Quick check · What can limit the rate?</h3>${questionOptions()}</div>${reasonBlock()}`:''}${activityFooter()}`}
function render(){if(current<0)renderHome();else renderModule();updateScoreUI()}
function onChoice(j){if(quiz.choiceRight)return;quiz.choice=j;if(j===modules[current].answer){quiz.choiceRight=true;addPoints(20,'correct answer');}else{quiz.choiceRight=false;quiz.reasonText=quiz.reasonText||'';}render()}
function onReason(){const input=document.getElementById('reasonInput');if(!input)return;const val=input.value.trim();quiz.reasonText=val;const keys=modules[current].reason.toLowerCase().split(/\s+/);if(val.length<12){quiz.reasonFeedback='Add a little more detail—explain your idea in a full sentence.';render();return}if(!keys.some(k=>val.toLowerCase().includes(k))){quiz.reasonFeedback='Not quite yet—use one of the scientific ideas in the hint, then explain why.';render();return}quiz.reasonDone=true;quiz.reasonFeedback='Reason accepted — excellent scientific thinking.';addPoints(15,'scientific reasoning');render()}
function action(name){const a=activity;
if(name==='water'){if(a.year===0&&!a.watered){a.watered=true;addPoints(2,'careful observation')} }
else if(name==='year'){if(a.watered&&a.year<5){a.year++;a.watered=false;if(a.year===5)showToast('Five years have passed. Now weigh both components.')}}
else if(name==='weigh'){if(a.year===5&&a.watered){a.weighed=true;addPoints(10,'experiment complete')}}
else if(name==='prism'){a.prism=true;addPoints(8,'spectrum observed')}
else if(name==='photon'){if(a.phase===0&&!a.energy){a.energy=true;addPoints(3,'chlorophyll energized')}}
else if(name==='split'){if(a.energy&&a.water<3){a.water++;addPoints(2,'water molecule split')}}
else if(name==='oxygen'){if(a.water>=3&&a.phase===0){a.phase=1;addPoints(8,'oxygen released')}}
else if(name==='co2'){if(a.phase===1&&a.co2<3){a.co2++;addPoints(2,'carbon captured')}}
else if(name==='glucose'){if(a.co2>=3){a.phase=2;addPoints(8,'glucose synthesized')}}
else if(name==='equation'){if(a.eq.join('|')==='6CO₂|6H₂O|C₆H₁₂O₆|6O₂'){a.eqDone=true;addPoints(12,'equation balanced')}else showToast('Check the coefficients and molecule order, then try again.')}
else if(name==='clearEquation'){a.eq=[null,null,null,null];a.eqActive=0;a.eqDone=false}
else if(name==='iodine'){a.tested[0]=true;if(!a.predicted){a.predicted=true;addPoints(3,'prediction recorded')}}
else if(name==='tapeIodine'){a.tested[1]=true;if(!a.predicted){a.predicted=true;addPoints(3,'prediction recorded')}}
else if(name==='optimize'){const rate=calcRate(+a.temp,+a.co2,+a.light);if(rate>=65){a.optimized=true;addPoints(12,'conditions optimized')}else showToast('Rate is '+rate+' — tune the conditions higher before locking in.')}
else if(name==='reason'){onReason();return}
