const pairData=[{label:"Double membrane",func:"Two protective membranes surround the chloroplast."},{label:"Stroma",func:"Fluid-filled space; site of light-independent reactions."},{label:"Grana",func:"Stacks of thylakoids with chlorophyll; site of light-dependent reactions."}];
const defaults={score:0,done:[false,false,false,false,false]};let saved={};try{saved=JSON.parse(localStorage.getItem('photosynthesisQuest')||'{}')}catch(e){}
let score=saved.score||0,done=saved.done||defaults.done.slice(),current=-1,activity={},quiz={choice:null,choiceRight:false,reasonDone:false,reasonText:'',reasonFeedback:''},toastTimer;
const app=document.getElementById('app');
function save(){try{localStorage.setItem('photosynthesisQuest',JSON.stringify({score,done}))}catch(e){}document.getElementById('topScore').textContent=String(score).padStart(3,'0')}
function addPoints(n,msg){score+=n;save();showToast(`+${n} Photosynthesis Points${msg?' · '+msg:''}`)}
function showToast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function fresh(i){return i===0?{year:0,watered:false,weighed:false}:i===1?{pairs:{},selectedLabel:null,prism:false}:i===2?{phase:0,water:0,co2:0,energy:false,eq:[null,null,null,null],eqActive:0,eqDone:false}:i===3?{tested:[false,false],predicted:false}:i===4?{temp:25,co2:420,light:65,farm:[],optimized:false,farmRewarded:false}:{} }
function openModule(i){current=i;activity=fresh(i);quiz={choice:null,choiceRight:false,reasonDone:false,reasonText:'',reasonFeedback:''};render()}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function activeDone(){const a=activity;return current===0?a.weighed:current===1?Object.keys(a.pairs).length===3&&a.prism:current===2?a.phase>=2&&a.co2>=3&&a.energy&&a.eqDone:current===3?a.tested.every(Boolean):a.optimized&&a.farm.length===3}
function home(){app.innerHTML=`<section class="home-grid"><div class="hero"><div class="eyebrow">A hands-on journey through plant science</div><h1>Photosynthesis<br><em>Quest</em>: Master<br>of Energy</h1><p class="hero-copy">How does a tiny seedling turn sunlight into a forest? Step into the lab, run the experiments, and follow the energy.</p><button class="button" data-open="${Math.max(0,done.findIndex(x=>!x))}">START YOUR QUEST <span class="arrow">↗</span></button><div class="hero-bottom"><div class="avatars"><i>🌿</i><i>🔬</i><i>☀️</i></div><span>5 field missions · Ages 11–14</span></div></div><div class="hero-art"><span class="orbit o1">☀️</span><span class="orbit o2">CO₂</span><span class="orbit o3">H₂O</span><span class="orbit o4">✦</span><div class="hero-leaf">🌿</div><span class="art-caption">FIG 01 · ENERGY IN MOTION</span></div></section><section class="home-modules"><div class="section-heading"><div><div class="eyebrow">Choose a mission</div><h2>Your field guide</h2></div><small>${done.filter(Boolean).length} OF 5 MISSIONS COMPLETE</small></div><div class="module-grid">${modules.map((m,i)=>`<article class="module-card ${done[i]?'done':''}" data-open="${i}"><span class="card-num">0${i+1} / 05</span><span class="card-icon">${m.icon}</span><h3>${m.short}</h3><p>${['Recreate the willow experiment.','Explore a plant cell’s power lab.','Turn light into a glucose model.','Run a starch-detective test.','Tune a vertical farm.'][i]}</p>${done[i]?'<span class="card-status">✓ COMPLETE</span>':''}</article>`).join('')}</div></section>`}
function sidebar(){return `<aside class="sidebar"><button class="back-link" data-home>← &nbsp;FIELD GUIDE</button><h2 class="sidebar-title">Your field guide</h2><p class="sidebar-desc">Five missions to master plant energy.</p><div class="progress-track"><span style="width:${done.filter(Boolean).length*20}%"></span></div><nav class="side-nav">${modules.map((m,i)=>`<div class="side-module ${i===current?'active':''} ${done[i]?'complete':''}" data-open="${i}"><span class="side-icon">${m.icon}</span><span class="side-label">${m.short}</span>${done[i]?'<span class="side-check">✓</span>':''}</div>`).join('')}</nav><div class="side-score">YOUR PHOTOSYNTHESIS POINTS<strong>✦ ${score}</strong></div></aside>`}
function render(){if(current<0){home();save();return}const m=modules[current];app.innerHTML=`<div class="game-grid">${sidebar()}<section class="content"><header class="module-heading"><div><div class="eyebrow">MISSION 0${current+1} · ${esc(m.kicker)}</div><h1>${esc(m.title)}</h1><p>${esc(m.desc)}</p></div><span class="level-tag">${done[current]?'✓ MASTERED':'FIELD LAB · 0'+(current+1)}</span></header><div class="lab-panel">${activityView()}${activeDone()?quizView():''}</div>${done[current]?'<div class="finish-note">Mission complete! Revisit the lab or head to another field mission. Your points are saved on this device.</div>':''}</section></div>`;save()}
function questionOptions(){const m=modules[current];return `<div class="options">${m.choices.map((x,j)=>`<button class="option ${quiz.choice===j?(j===m.answer?'correct':'wrong'):''}" data-choice="${j}" ${quiz.choiceRight?'disabled':''}>${String.fromCharCode(65+j)}. ${esc(x)}</button>`).join('')}</div><div class="feedback ${quiz.choice!==null&&!quiz.choiceRight?'bad':''}">${quiz.choiceRight?'Correct! A sharp scientific observation.':quiz.choice!==null?'Not quite—read the evidence and try again.':''}</div>`}
function quizView(){return `<div class="challenge"><h3>Quick check · Choose the best explanation</h3>${questionOptions()}</div><div class="challenge"><h3>Give a reason · Think like a scientist</h3><p class="reason-hint">${esc(modules[current].hint)}</p><div class="reason-row"><input id="reasonInput" placeholder="Explain your thinking in a sentence…" value="${esc(quiz.reasonText)}" ${quiz.reasonDone?'disabled':''}><button class="activity-btn primary" data-action="reason" ${quiz.reasonDone?'disabled':''}>${quiz.reasonDone?'Reason saved ✓':'Check my reason'}</button></div><div class="feedback">${esc(quiz.reasonFeedback)}</div></div>${footer()}`}
function footer(){return `<div class="activity-footer"><span class="quest-progress">${done[current]?'MISSION MASTERED':activeDone()?'ACTIVITY COMPLETE · ANSWER THE CHALLENGES':'COMPLETE THE LAB TO UNLOCK YOUR CHALLENGE'}</span>${activeDone()&&quiz.choiceRight&&quiz.reasonDone&&!done[current]?`<button class="button lime" data-action="finish">${current===4?'COMPLETE QUEST':'NEXT MISSION'} <span class="arrow">→</span></button>`:''}</div>`}
function willow(){const a=activity;return `<div class="panel-top"><span class="panel-label">THE WILLOW EXPERIMENT · 1648–1653</span><span class="panel-step">${a.weighed?'RESULTS RECORDED':`YEAR ${Math.min(a.year+1,5)} OF 5`}</span></div><div class="activity-row"><div class="activity-visual"><span class="sun">☀️</span><span class="sapling">${a.year<2?'🌱':a.year<4?'🪴':'🌳'}</span><span class="soil"></span></div><div class="activity-info"><h3>${a.weighed?'A surprising result.':'Grow the willow.'}</h3><p>${a.weighed?'The tree gained enormous mass, while the dry soil barely changed. Where did the tree’s new material come from?':`Plant the ${a.year===0?'sapling':'growing willow'} in dry soil. Water it once each simulated year; sunlight and air are part of the experiment too.`}</p><div class="year-dots">${[1,2,3,4,5].map(y=>`<span class="year-dot ${y<=a.year?'active':''}">${y}</span>`).join('')}</div><div class="stat-row"><div class="stat-box"><span>WILLOW MASS</span><strong>${a.weighed?'74.8 kg':`${Math.round(.06+a.year*14.94)} kg`}</strong></div><div class="stat-box"><span>DRY SOIL</span><strong>${a.weighed?'−0.06 kg':`${a.year===0?'90.0':(90-a.year*.01).toFixed(2)} kg`}</strong></div></div><div class="inline-actions">${!a.weighed?(a.year>=5?'<button class="activity-btn primary" data-action="weigh">Weigh the results ⚖</button>':`<button class="activity-btn primary" data-action="${a.watered?'year':'water'}">${a.watered?'Advance one year ↗':'💧 Water the willow'}</button>`):'<span class="mini-note">The tiny soil change cannot account for the tree’s growth.</span>'}</div><div class="feedback">${a.watered&&!a.weighed?'Water absorbed. Advance time to continue.':''}</div></div></div>${a.weighed?'<div class="mini-note"><b>Field note:</b> Van Helmont’s measurement was important, but he did not account for gases. Modern science shows plants make most of their biomass from carbon dioxide and water—not soil.</div>':''}${footer()}`}
function chloroplast(){const a=activity;return `<div class="panel-top"><span class="panel-label">PLANT CELL · CHLOROPLAST ZOOM</span><span class="panel-step">${Object.keys(a.pairs).length}/3 STRUCTURES MATCHED</span></div><div class="activity-row"><div class="activity-visual"><span class="cell-art">🟢</span><div class="chloroplast-scene"><div class="grana-stack"><i></i><i></i><i></i></div><span class="stroma-text">stroma</span><div class="grana-stack"><i></i><i></i><i></i></div></div></div><div class="activity-info"><h3>Match the parts.</h3><p>Drag a structure onto its function—or tap one from each column. Match all three to open the light lab.</p><div class="match-grid"><div class="match-column"><h4>STRUCTURE</h4>${pairData.map((p,i)=>`<div class="match-item ${a.pairs[i]!==undefined?'paired':''}" draggable="true" data-label="${i}">${a.pairs[i]!==undefined?'✓ ':''}${p.label}</div>`).join('')}</div><div class="match-column"><h4>FUNCTION</h4>${pairData.map((p,i)=>`<div class="match-item ${Object.values(a.pairs).includes(i)?'paired':''}" data-function="${i}">${Object.values(a.pairs).includes(i)?'✓ ':''}${p.func}</div>`).join('')}</div></div></div></div><div class="feedback" id="activityFeedback">${a.prism?'🌈 Visible colours separate. Chlorophyll absorbs light energy; its electrons become excited.':'Tip: double membrane = boundary; stroma = fluid; grana = stacks.'}</div><div class="challenge"><h3>Physics & chemistry link · Shine white light through a prism</h3><div class="prism-strip"></div><p class="reason-hint">A triangular prism separates white light into a visible spectrum. What happens to chlorophyll’s electrons when it absorbs light?</p><button class="activity-btn ${a.prism?'':'primary'}" data-action="prism" ${a.prism?'disabled':''}>${a.prism?'Spectrum observed ✓':'Pass light through the prism 🌈'}</button></div>${Object.keys(a.pairs).length===3&&a.prism?quizView():footer()}`}
function arcade(){const a=activity;let box='';if(a.phase===0)box=`<div class="activity-info"><h3>Stage A · Charge the grana</h3><p>Light excites chlorophyll. Split water, release oxygen, and store energy for the next stage.</p><div class="stage-meter">${[1,2,3].map(n=>`<i class="meter-cell ${n<=a.water?'on':''}"></i>`).join('')}</div><div class="inline-actions"><button class="activity-btn primary" data-action="photon" ${a.energy?'disabled':''}>☀ Absorb a photon</button><button class="activity-btn" data-action="split" ${!a.energy||a.water>=3?'disabled':''}>💧 Split water (${a.water}/3)</button><button class="activity-btn" data-action="oxygen" ${a.water<3?'disabled':''}>Release O₂ + store energy</button></div><div class="feedback">${a.energy?(a.water>=3?'Water split! Release oxygen and store energy.':'Chlorophyll excited! Now split three water molecules.'):' '}</div></div>`;else if(a.phase===1)box=`<div class="activity-info"><h3>Stage B · Build in the stroma</h3><p>Use stored energy and hydrogen with carbon dioxide in the Calvin cycle. Collect three CO₂ molecules to build one glucose.</p><div class="stat-row"><div class="stat-box"><span>STORED ENERGY</span><strong>⚡ Ready</strong></div><div class="stat-box"><span>CO₂ COLLECTED</span><strong>${a.co2} / 3</strong></div></div><div class="inline-actions"><button class="activity-btn primary" data-action="co2" ${a.co2>=3?'disabled':''}>＋ Add CO₂</button><button class="activity-btn" data-action="glucose" ${a.co2<3?'disabled':''}>⚡ Assemble glucose</button></div></div>`;else box=`<div class="activity-info"><h3>Glucose assembled! ✨</h3><p>Balance the photosynthesis equation. Fill each slot with the correct molecule and coefficient.</p><div class="molecule-row"><div class="molecule">CARBON DIOXIDE<div class="atom-line"><i class="atom o">O</i><i class="atom bond"></i><i class="atom c">C</i><i class="atom bond"></i><i class="atom o">O</i></div></div><div class="molecule">WATER<div class="atom-line"><i class="atom h">H</i><i class="atom bond"></i><i class="atom o">O</i><i class="atom bond"></i><i class="atom h">H</i></div></div><div class="molecule">OXYGEN<div class="atom-line"><i class="atom o">O</i><i class="atom bond"></i><i class="atom o">O</i></div></div></div><div class="equation">${a.eq.map((x,j)=>`<div class="equation-slot ${x?'filled':''}" data-eq-slot="${j}">${x||['Reactant 1','Reactant 2','Product 1','Product 2'][j]}</div>${j===0?'<span>+</span>':j===1?'<span>→</span>':j===2?'<span>+</span>':''}`).join('')}</div><div class="equation-controls">${['6CO₂','6H₂O','C₆H₁₂O₆','6O₂'].map(x=>`<button class="activity-btn" data-eq-value="${x}">${x}</button>`).join('')}</div><div class="inline-actions" style="justify-content:center"><button class="activity-btn primary" data-action="equation">Check balanced equation</button><button class="activity-btn" data-action="clearEquation">Reset</button></div><div class="feedback" style="text-align:center">${a.eqDone?'Perfectly balanced! 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂':'Select a slot, then a molecule. Balance atoms on both sides.'}</div></div>`;
return `<div class="panel-top"><span class="panel-label">${a.phase===0?'STAGE A · LIGHT-DEPENDENT · GRANA':a.phase===1?'STAGE B · CALVIN CYCLE · STROMA':'MOLECULAR MODELLING · BALANCED EQUATION'}</span><span class="panel-step">${a.phase+1} / 03</span></div><div class="activity-row"><div class="activity-visual">${a.phase===2?'<div style="font-size:45px;animation:pulse 1.4s infinite">🍬</div>':`<div style="text-align:center"><div style="font-size:39px">${a.energy?'✨':'☀️'}</div><div class="chloroplast-scene" style="width:128px;height:76px;border-width:6px;margin:6px auto"><div class="grana-stack"><i></i><i></i><i></i></div><span class="stroma-text">${a.phase?'stroma':'grana'}</span></div><div class="molecule-row"><span class="molecule">H₂O × ${a.water}</span><span class="molecule">O₂</span></div></div>`}</div>${box}</div>${a.phase===2&&a.eqDone?quizView():footer()}`}
function activityView(){return current===0?willow():current===1?chloroplast():current===2?arcade():current===3?detective():farm()}

