1: const modules=[
2:  {title:"The willow mystery",short:"Van Helmont’s experiment",icon:"🌱",kicker:"A 17TH-CENTURY FIELD EXPERIMENT",desc:"Can a tiny sapling gain 75 kilograms without eating soil? Recreate Jan Baptista van Helmont’s famous five-year experiment.",question:"Why did the soil lose only a little mass while the willow grew so much?",choices:["The tree absorbed most of its mass from water and carbon dioxide in the air.","The roots secretly turned stones into wood.","The soil changed into water and vanished.","The gardener added extra soil each year."],answer:0,reason:"water and air",hint:"Try to include: water, air, carbon dioxide, or minerals.",kind:"willow"},
3:  {title:"Inside the chloroplast",short:"The green power lab",icon:"🔬",kicker:"VIRTUAL LAB · STRUCTURE MATCHING",desc:"Zoom into a leaf cell and explore the tiny organelles that capture light and turn it into stored chemical energy.",question:"A beam of visible light enters a chloroplast. Which statement is correct?",choices:["Chlorophyll absorbs light; energized electrons help transfer energy in the grana.","The stroma is a double membrane that absorbs all light.","The chloroplast releases light to split glucose into soil.","Only invisible sound waves can excite chlorophyll."],answer:0,reason:"excited",hint:"Try to include: chlorophyll, visible light, or excited electrons.",kind:"chloroplast"},
4:  {title:"Two-stage energy arcade",short:"The two-stage arcade",icon:"⚡",kicker:"LIGHT IN · SUGAR OUT",desc:"Power up active chlorophyll, split water, and shuttle energy into the Calvin cycle to assemble a glucose molecule.",question:"Which sequence best describes photosynthesis?",choices:["Light reactions split water and release oxygen; the Calvin cycle uses CO₂ and stored energy to build sugar.","The Calvin cycle splits oxygen in the grana to make sunlight.","Plants turn glucose into carbon dioxide using only soil.","Water is made from oxygen during the light-independent stage."],answer:0,reason:"grana",hint:"Try to include: grana, stroma, water, oxygen, or glucose.",kind:"arcade"},
5:  {title:"The starch detective",short:"The starch detective",icon:"🧪",kicker:"LAB NOTE · IODINE TEST",desc:"Test a variegated leaf and one partly covered with opaque tape. Find out exactly where a plant made starch.",question:"After the iodine test, which parts of a leaf turn blue-black?",choices:["Green areas exposed to light, because they made starch.","Every part of both leaves, because iodine is blue.","White areas only, because they reflect more light.","Covered areas only, because tape traps heat."],answer:0,reason:"chlorophyll",hint:"Try to include: chlorophyll, light, or starch.",kind:"detective"},
6:  {title:"City of the future",short:"Vertical farm architect",icon:"🏙️",kicker:"GROW MORE · USE LESS LAND",desc:"Tune the growing conditions, discover what limits photosynthesis, then design a high-rise farm for a crowded city.",question:"Why can a vertical farm grow crops on many floors?",choices:["Artificial lights and hydroponics let plants grow indoors without relying on large areas of fertile soil.","Plants do not need carbon dioxide indoors.","The tallest floors receive unlimited sunlight at every hour.","Hydroponics means plants grow without water."],answer:0,reason:"light",hint:"Try to include: artificial light, hydroponics, or land.",kind:"farm"}
7: ];
