9: const defaults={score:0,done:[false,false,false,false,false]};let saved={};try{saved=JSON.parse(localStorage.getItem('photosynthesisQuest')||'{}')}catch(e){}
10: let score=saved.score||0,done=saved.done||defaults.done.slice(),current=-1,activity={},quiz={choice:null,choiceRight:false,reasonDone:false,reasonText:'',reasonFeedback:''},toastTimer;
11: const app=document.getElementById('app');
12: function save(){try{localStorage.setItem('photosynthesisQuest',JSON.stringify({score,done}))}catch(e){}document.getElementById('topScore').textContent=String(score).padStart(3,'0')}
13: function addPoints(n,msg){score+=n;save();showToast(`+${n} Photosynthesis Points${msg?' · '+msg:''}`)}
14: function showToast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
15: function fresh(i){return i===0?{year:0,watered:false,weighed:false}:i===1?{pairs:{},selectedLabel:null,prism:false}:i===2?{phase:0,water:0,co2:0,energy:false,eq:[null,null,null,null],eqActive:0,eqDone:false}:i===3?{tested:[false,false],predicted:false}:i===4?{temp:25,co2:420,light:65,farm:[],optimized:false,farmRewarded:false}:{} }
16: function openModule(i){current=i;activity=fresh(i);quiz={choice:null,choiceRight:false,reasonDone:false,reasonText:'',reasonFeedback:''};render()}
17: function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
