"atom bond"></i><i class="atom o">O</i><i class="atom bond"></i><i class="atom h">H</i></div></div><div class="molecule">OXYGEN<div class="atom-line"><i class="atom o">O</i><i class="atom bond"></i><i class="atom o">O</i></div></div></div><div class="equation">${a.eq.map((x,j)=>`<div class="equation-slot ${x?'filled':''}" data-eq-slot="${j}">${x||['Reactant 1','Reactant 2','Product 1','Product 2'][j]}</div>${j===0?'<span>+</span>':j===1?'<span>→</span>':j===2?'<span>+</span>':''}`).join('')}</div><div class="equation-controls">${['6CO₂','6H₂O','C₆H₁₂O₆','6O₂'].map(x=>`<button class="activity-btn" data-eq-value="${x}">${x}</button>`).join('')}</div><div class="inline-actions" style="justify-content:center"><button class="activity-btn primary" data-action="equation">Check balanced equation</button><button class="activity-btn" data-action="clearEquation">Reset</button></div><div class="feedback" style="text-align:center">${a.eqDone?'Perfectly balanced! 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂':'Select a slot, then a molecule. Balance atoms on both sides.'}</div></div>`;
return `<div class="panel-top"><span class="panel-label">${a.phase===0?'STAGE A · LIGHT-DEPENDENT · GRANA':a.phase===1?'STAGE B · CALVIN CYCLE · STROMA':'MOLECULAR MODELLING · BALANCED EQUATION'}</span><span class="panel-step">${a.phase+1} / 03</span></div><div class="activity-row"><div class="activity-visual">${a.phase===2?'<div style="font-size:45px;animation:pulse 1.4s infinite">🍬</div>':`<div style="text-align:center"><div style="font-size:39px">${a.energy?'✨':'☀️'}</div><div class="chloroplast-scene" style="width:128px;height:76px;border-width:6px;margin:6px auto"><div class="grana-stack"><i></i><i></i><i></i></div><span class="stroma-text">${a.phase?'stroma':'grana'}</span></div><div class="molecule-row"><span class="molecule">H₂O × ${a.water}</span><span class="molecule">O₂</span></div></div>`}</div>${box}</div>${a.phase===2&&a.eqDone?quizView():footer()}`}
