function home(){app.innerHTML=`<section class="home-grid"><div class="hero"><div class="eyebrow">A hands-on journey through plant science</div><h1>Photosynthesis<br><em>Quest</em>: Master<br>of Energy</h1><p class="hero-copy">How does a tiny seedling turn sunlight into a forest? Step into the lab, run the experiments, and follow the energy.</p><button class="button" data-open="${Math.max(0,done.findIndex(x=>!x))}">START YOUR QUEST <span class="arrow">↗</span></button><div class="hero-bottom"><div class="avatars"><i>🌿</i><i>🔬</i><i>☀️</i></div><span>5 field missions · Ages 11–14</span></div></div><div class="hero-art"><span class="orbit o1">☀️</span><span class="orbit o2">CO₂</span><span class="orbit o3">H₂O</span><span class="orbit o4">✦</span><div class="hero-leaf">🌿</div><span class="art-caption">FIG 01 · ENERGY IN MOTION</span></div></section><section class="home-modules"><div class="section-heading"><div><div class="eyebrow">Choose a mission</div><h2>Your field guide</h2></div><small>${done.filter(Boolean).length} OF 5 MISSIONS COMPLETE</small></div><div class="module-grid">${modules.map((m,i)=>`<article class="module-card ${done[i]?'done':''}" data-open="${i}" tabindex="0" role="button"><span class="card-num">0${i+1} / 05</span><span class="card-icon">${m.icon}</span><h3>${m.short}</h3><p>${['Recreate the willow experiment.','Explore a plant cell’s power lab.','Turn light into a glucose model.','Run a starch-detective test.','Tune a vertical farm.'][i]}</p>${done[i]?'<span class="card-status">✓ COMPLETE</span>':''}</article>`).join('')}</div></section>`}
function sidebar(){return `<aside class="sidebar"><button class="back-link" data-home>← &nbsp;FIELD GUIDE</button><h2 class="sidebar-title">Your field guide</h2><p class="sidebar-desc">Five missions to master plant energy.</p><div class="progress-track"><span style="width:${done.filter(Boolean).length*20}%"></span></div><nav class="side-nav">${modules.map((m,i)=>`<button class="side-module ${i===current?'active':''} ${done[i]?'complete':''}" data-open="${i}"><span class="side-icon">${m.icon}</span><span class="side-label">${m.short}</span>${done[i]?'<span class="side-check">✓</span>':''}</button>`).join('')}</nav><div class="side-score">YOUR PHOTOSYNTHESIS POINTS<strong>✦ ${score}</strong></div></aside>`}
function render(){if(current<0){home();save();return}const m=modules[current];app.innerHTML=`<div class="game-grid">${sidebar()}<section class="content"><header class="module-heading"><div><div class="eyebrow">MISSION 0${current+1} · ${esc(m.kicker)}</div><h1>${esc(m.title)}</h1><p>${esc(m.desc)}</p></div><span class="level-tag">${done[current]?'✓ MASTERED':'FIELD LAB · 0'+(current+1)}</span></header><div class="lab-panel">${activityView()}${activeDone()?quizView():''}</div>${done[current]?'<div class="finish-note">Mission complete! Revisit the lab or head to another field mission. Your points are saved on this device.</div>':''}</section></div>`;save()}
function questionOptions(){const m=modules[current];return `<div class="options">${m.choices.map((x,j)=>`<button class="option ${quiz.choice===j?(j===m.answer?'correct':'wrong'):''}" data-choice="${j}" ${quiz.choiceRight?'disabled':''}>${String.fromCharCode(65+j)}. ${esc(x)}</button>`).join('')}</div><div class="feedback ${quiz.choice!==null&&!quiz.choiceRight?'bad':''}">${quiz.choiceRight?'Correct! A sharp scientific observation.':quiz.choice!==null?'Not quite—read the evidence and try again.':''}</div>`}
function quizView(){return `<div class="challenge"><h3>Quick check · Choose the best explanation</h3>${questionOptions()}</div><div class="challenge"><h3>Give a reason · Think like a scientist</h3><p class="reason-hint">${esc(modules[current].hint)}</p><div class="reason-row"><input id="reasonInput" placeholder="Explain your thinking in a sentence…" value="${esc(quiz.reasonText)}" ${quiz.reasonDone?'disabled':''}><button class="activity-btn primary" data-action="reason" ${quiz.reasonDone?'disabled':''}>${quiz.reasonDone?'Reason saved ✓':'Check my reason'}</button></div><div class="feedback">${esc(quiz.reasonFeedback)}</div></div>${footer()}`}
function footer(){return `<div class="activity-footer"><span class="quest-progress">${done[current]?'MISSION MASTERED':activeDone()?'ACTIVITY COMPLETE · ANSWER THE CHALLENGES':'COMPLETE THE LAB TO UNLOCK YOUR CHALLENGE'}</span>${activeDone()&&quiz.choiceRight&&quiz.reasonDone&&!done[current]?`<button class="button lime" data-action="finish">${current===4?'COMPLETE QUEST':'NEXT MISSION'} <span class="arrow">→</span></button>`:''}</div>`}

