function footer(){return `<div class="activity-footer"><span class="quest-progress">${done[current]?'MISSION MASTERED':activeDone()?'ACTIVITY COMPLETE · ANSWER THE CHALLENGES':'COMPLETE THE LAB TO UNLOCK YOUR CHALLENGE'}</span>${activeDone()&&quiz.choiceRight&&quiz.reasonDone&&!done[current]?`<button class="button lime" data-action="finish">${current===4?'COMPLETE QUEST':'NEXT MISSION'} <span class="arrow">→</span></button>`:''}</div>`}
function willow(){const a=activity;return `<div class="panel-top"><span class="panel-label">THE WILLOW EXPERIMENT · 1648–1653</span><span class="panel-step">${a.weighed?'RESULTS RECORDED':`YEAR ${Math.min(a.year+1,5)} OF 5`}</span></div><div class="activity-row"><div class="activity-visual"><span class="sun">☀️</span><span class="sapling">${a.year<2?'🌱':a.year<4?'🪴':'🌳'}</span><span class="soil"></span></div><div class="activity-info"><h3>${a.weighed?'A surprising result.':'Grow the willow.'}</h3><p>${a.weighed?'The tree gained enormous mass, while the dry soil barely changed. Where did the tree’s new material come from?':`Plant the ${a.year===0?'sapling':'growing willow'} in dry soil. Water it once each simulated year; sunlight and air are part of the experiment too.`}</p><div class="year-dots">${[1,2,3,4,5].map(y=>`<span class="year-dot ${y<=a.year?'active':''}">${y}</span>`).join('')}</div><div class="stat-row"><div class="stat-box"><span>WILLOW MASS</span><strong>${a.weighed?'74.8 kg':`${Math.round(.06+a.year*14.94)} kg`}</strong></div><div class="stat-box"><span>DRY SOIL</span><strong>${a.weighed?'−0.06 kg':`${a.year===0?'90.0':(90-a.year*.01).toFixed(2)} kg`}</strong></div></div><div class="inline-actions">${!a.weighed?(a.year>=5?'<button class="activity-btn primary" data-action="weigh">Weigh the results ⚖</button>':`<button class="activity-btn primary" data-action="${a.watered?'year':'water'}">${a.watered?'Advance one year ↗':'💧 Water the willow'}</button>`):'<span class="mini-note">The tiny soil change cannot account for the tree’s growth.</span>'}</div><div class="feedback">${a.watered&&!a.weighed?'Water absorbed. Advance time to continue.':''}</div></div></div>${a.weighed?'<div class="mini-note"><b>Field note:</b> Van Helmont’s measurement was important, but he did not account for gases. Modern science shows plants make most of their biomass from carbon dioxide and water—not soil.</div>':''}${footer()}`}
function chloroplast(){const a=activity;return `<div class="panel-top"><span class="panel-label">PLANT CELL · CHLOROPLAST ZOOM</span><span class="panel-step">${Object.keys(a.pairs).length}/3 STRUCTURES MATCHED</span></div><div class="activity-row"><div class="activity-visual"><span class="cell-art">🟢</span><div class="chloroplast-scene"><div class="grana-stack"><i></i><i></i><i></i></div><span class="stroma-text">stroma</span><div class="grana-stack"><i></i><i></i><i></i></div></div></div><div class="activity-info"><h3>Match the parts.</h3><p>Tap one structure and then its function. Match all three to open the light lab.</p><div class="match-grid"><div class="match-column"><h4>STRUCTURE</h4>${pairData.map((p,i)=>`<button class="match-item ${a.pairs[i]!==undefined?'paired':''} ${a.selectedLabel===i?'selected':''}" data-label="${i}" ${a.pairs[i]!==undefined?'disabled':''}>${a.pairs[i]!==undefined?'✓ ':''}${p.label}</button>`).join('')}</div><div class="match-column"><h4>FUNCTION</h4>${pairData.map((p,i)=>`<button class="match-item ${Object.values(a.pairs).includes(i)?'paired':''}" data-function="${i}" ${Object.values(a.pairs).includes(i)?'disabled':''}>${Object.values(a.pairs).includes(i)?'✓ ':''}${p.func}</button>`).join('')}</div></div><div class="feedback">${esc(a.feedback||'Tip: double membrane = boundary; stroma = fluid; grana = stacks.')}</div></div></div><div class="challenge"><h3>Physics & chemistry link · Shine white light through a prism</h3><div class="prism-strip"></div><p class="reason-hint">A triangular prism separates white light into a visible spectrum. What happens to chlorophyll’s electrons when it absorbs light?</p><button class="activity-btn ${a.prism?'':'primary'}" data-action="prism" ${a.prism?'disabled':''}>${a.prism?'Spectrum observed ✓':'Pass light through the prism 🌈'}</button><div class="feedback">${a.prism?'Chlorophyll absorbs some visible wavelengths; absorbed energy excites electrons.':''}</div></div>${Object.keys(a.pairs).length===3&&a.prism?quizView():footer()}`}
function arcade(){const a=activity;let box='';if(a.phase===0)box=`<div class="activity-info"><h3>Stage A · Charge the grana</h3><p>Light excites chlorophyll. Split water, release oxygen, and store energy for the next stage.</p><div class="stage-meter">${[1,2,3].map(n=>`<i class="meter-cell ${n<=a.water?'on':''}"></i>`).join('')}</div><div class="inline-actions"><button class="activity-btn primary" data-action="photon" ${a.energy?'disabled':''}>☀ Absorb a photon</button><button class="activity-btn" data-action="split" ${!a.energy||a.water>=3?'disabled':''}>💧 Split water (${a.water}/3)</button><button class="activity-btn" data-action="oxygen" ${a.water<3?'disabled':''}>Release O₂ + store energy</button></div><div class="feedback">${a.energy?(a.water>=3?'Water split! Release oxygen and store energy.':'Chlorophyll excited! Now split three water molecules.'):'Activate chlorophyll with light first.'}</div></div>`;else if(a.phase===1)box=`<div class="activity-info"><h3>Stage B · Build in the stroma</h3><p>Use stored energy and hydrogen with carbon dioxide in the Calvin cycle. Collect three CO₂ molecules to build one glucose.</p><div class="stat-row"><div class="stat-box"><span>STORED ENERGY</span><strong>⚡ Ready</strong></div><div class="stat-box"><span>CO₂ COLLECTED</span><strong>${a.co2} / 3</strong></div></div><div class="inline-actions"><button class="activity-btn primary" data-action="co2" ${a.co2>=3?'disabled':''}>＋ Add CO₂</button><button class="activity-btn" data-action="glucose" ${a.co2<3?'disabled':''}>⚡ Assemble glucose</button></div></div>`;else box=`<div class="activity-info"><h3>Glucose assembled! ✨</h3><p>Balance the photosynthesis equation. Fill each slot with the correct molecule and coefficient.</p><div class="molecule-row"><div class="molecule">CARBON DIOXIDE<div class="atom-line"><i class="atom o">O</i><i class="atom bond"></i><i class="atom c">C</i><i class="atom bond"></i><i class="atom o">O</i></div></div><div class="molecule">WATER<div class="atom-line"><i class="atom h">H</i><i class="atom bond"></i><i class="atom o">O</i><i class="atom bond"></i><i class="atom h">H</i></div></div><div class="molecule">OXYGEN<div class="atom-line"><i class="atom o">O</i><i class="atom bond"></i><i class="atom o">O</i></div></div></div><div class="equation">${a.eq.map((x,j)=>`<button class="equation-slot ${x?'filled':''} ${a.eqActive===j?'selected':''}" data-eq-slot="${j}">${x||['Reactant 1','Reactant 2','Product 1','Product 2'][j]}</button>${j===0?'<span>+</span>':j===1?'<span>→</span>':j===2?'<span>+</span>':''}`).join('')}</div><div class="equation-controls">${['6CO₂','6H₂O','C₆H₁₂O₆','6O₂'].map(x=>`<button class="activity-btn" data-eq-value="${x}">${x}</button>`).join('')}</div><div class="inline-actions" style="justify-content:center"><button class="activity-btn primary" data-action="equation">Check balanced equation</button><button class="activity-btn" data-action="clearEquation">Reset</button></div><div class="feedback" style="text-align:center">${esc(a.feedback|| (a.eqDone?'Perfectly balanced! 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂':'Select a slot, then a molecule. Balance atoms on both sides.'))}</div></div>`;return `<div class="panel-top"><span class="panel-label">${a.phase===0?'STAGE A · LIGHT-DEPENDENT · GRANA':a.phase===1?'STAGE B · CALVIN CYCLE · STROMA':'MOLECULAR MODELLING · BALANCED EQUATION'}</span><span class="panel-step">${a.phase+1} / 03</span></div><div class="activity-row"><div class="activity-visual">${a.phase===2?'<div style="font-size:45px;animation:pulse 1.4s infinite">🍬</div>':`<div style="text-align:center"><div style="font-size:39px">${a.energy?'✨':'☀️'}</div><div class="chloroplast-scene" style="width:128px;height:76px;border-width:6px;margin:6px auto"><div class="grana-stack"><i></i><i></i><i></i></div><span class="stroma-text">${a.phase?'stroma':'grana'}</span></div><div class="molecule-row"><span class="molecule">H₂O × ${a.water}</span><span class="molecule">O₂</span></div></div>`}</div>${box}</div>${a.phase===2&&a.eqDone?quizView():footer()}`}

