function activityView(){return current===0?willow():current===1?chloroplast():current===2?arcade():current===3?detective():farm()}
function renderComplete(){app.innerHTML=`<section class="complete-screen"><div class="eyebrow">ALL FIVE MISSIONS COMPLETE</div><div class="complete-icon">🌿</div><h1>You're a Master of Energy!</h1><p>You followed light from chlorophyll to glucose, tested leaves for starch, and designed a vertical farm.</p><div class="final-score">✦ ${score} Photosynthesis Points</div><button class="button" data-home>RETURN TO FIELD GUIDE <span class="arrow">↗</span></button></section>`}
function finishMission(){if(!activeDone()||!quiz.choiceRight||!quiz.reasonDone)return;const wasDone=done[current];done[current]=true;if(!wasDone)award('mission-complete',50,'mission complete');save();if(current===4&&done.every(Boolean)){current=-1;renderComplete();return}if(current<4){openModule(current+1);return}current=-1;render()}
function setPairFunction(i){const a=activity;if(a.selectedLabel===null){a.feedback='Choose a structure first.';render();return}const label=a.selectedLabel;a.selectedLabel=null;if(label===i){a.pairs[label]=i;a.feedback=`Correct match: ${pairData[label].label}.`;if(Object.keys(a.pairs).length===3)award('structures',15,'chloroplast structures matched')}else a.feedback='Not quite. Think about the clue: boundary, fluid, or stacks of thylakoids.';render()}
function handleAction(button){const action=button.dataset.action,a=activity;if(action==='water'){a.watered=true;render()}else if(action==='year'){a.year++;a.watered=false;if(a.year===5)award('willow-years',10,'five years of growth');render()}else if(action==='weigh'){a.weighed=true;award('willow-result',15,'experiment complete');render()}else if(action==='prism'){a.prism=true;award('prism',10,'light spectrum explored');render()}else if(action==='photon'){a.energy=true;render()}else if(action==='split'){if(a.energy&&a.water<3)a.water++;render()}else if(action==='oxygen'){if(a.water>=3){a.phase=1;award('light-stage',15,'light reactions complete');render()}}else if(action==='co2'){if(a.co2<3)a.co2++;render()}else if(action==='glucose'){if(a.co2>=3){a.phase=2;render()}}else if(action==='equation'){if(a.eq.join('|')==='6CO₂|6H₂O|C₆H₁₂O₆|6O₂'){a.eqDone=true;a.feedback='Perfectly balanced! 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂';award('equation',20,'equation balanced')}else{a.feedback='Not balanced yet. Check the coefficient and molecule in every slot.'}render()}else if(action==='clearEquation'){a.eq=[null,null,null,null];a.eqActive=null;a.eqDone=false;a.feedback='Equation reset. Fill all four slots.';render()}else if(action==='testLeaf'){const i=Number(button.dataset.leaf);a.tested[i]=true;award(`leaf-${i}`,8,'iodine test complete');render()}else if(action==='optimize'){if(a.light>=70&&a.co2>=700&&a.temp>=22&&a.temp<=32){a.optimized=true;award('farm-optimized',15,'growth factors optimized')}else showToast('Try more light, more CO₂, and a suitable temperature.');render()}else if(action==='reason'){const input=document.getElementById('reasonInput'),text=(input?.value||'').trim();quiz.reasonText=text;const words=modules[current].reason.toLowerCase().split(/\s+/);const accepted=current===0?['water','air','carbon dioxide','co2']:current===1?['excited','chlorophyll','light']:current===2?['grana','stroma','water','oxygen','glucose']:current===3?['chlorophyll','light','starch']:['light','artificial','hydroponic','land','space'];if(text.length<12){quiz.reasonFeedback='Add a little more detail—write a complete scientific reason.'}else if(!accepted.some(w=>text.toLowerCase().includes(w))){quiz.reasonFeedback=`Try using one of these science ideas: ${modules[current].hint.replace('Try to include: ','')}`}else{quiz.reasonDone=true;quiz.reasonFeedback='Strong scientific reasoning! Your explanation connects evidence to the idea.';award('reason',15,'scientific reasoning')}render()}}
app.addEventListener('click',e=>{const target=e.target.closest('button,[data-open],[data-home]');if(!target)return;if(target.hasAttribute('data-home')){current=-1;render();return}if(target.dataset.open!==undefined){openModule(Number(target.dataset.open));return}if(target.dataset.label!==undefined){const i=Number(target.dataset.label);if(activity.pairs[i]!==undefined)return;activity.selectedLabel=i;activity.feedback=`Now choose the matching function for ${pairData[i].label}.`;render();return}if(target.dataset.function!==undefined){setPairFunction(Number(target.dataset.function));return}if(target.dataset.choice!==undefined){const choice=Number(target.dataset.choice);quiz.choice=choice;quiz.choiceRight=choice===modules[current].answer;if(quiz.choiceRight)award('quiz',15,'quick check correct');render();return}if(target.dataset.eqSlot!==undefined){activity.eqActive=Number(target.dataset.eqSlot);render();return}if(target.dataset.eqValue!==undefined){if(activity.eqActive===null){activity.feedback='Select an equation slot first.';render();return}activity.eq[activity.eqActive]=target.dataset.eqValue;activity.eqActive=null;activity.feedback='';render();return}if(target.dataset.crop!==undefined){const crop=Number(target.dataset.crop),selected=activity.farm.indexOf(crop);if(selected>=0)activity.farm.splice(selected,1);else if(activity.farm.length<3)activity.farm.push(crop);if(activity.farm.length===3&&!claimed.has(`${current}-farm-design`))award('farm-design',10,'farm designed');render();return}if(target.dataset.action==='finish'){finishMission();return}if(target.dataset.action){handleAction(target)}});
app.addEventListener('input',e=>{if(e.target.id==='reasonInput')quiz.reasonText=e.target.value});
app.addEventListener('change',e=>{const factor=e.target.dataset.factor;if(!factor)return;activity[factor]=Number(e.target.value);render()});
app.addEventListener('keydown',e=>{if(e.target.matches('[data-open]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openModule(Number(e.target.dataset.open))}if(e.target.id==='reasonInput'&&e.key==='Enter'){e.preventDefault();document.querySelector('[data-action="reason"]')?.click()}});
if(done.length!==5)done=defaults.done.slice();if(done.every(Boolean)){renderComplete();save()}else render();

